/* orbit. – persönlicher Studienplaner, unabhängig von Frameworks und Tracking */
(() => {
'use strict';
const D=window.ORBIT_DATA, KEY='orbit-ibw-v2', $=(q)=>document.querySelector(q);
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01"/>',check:'<path d="m4 12 5 5L20 6"/>',book:'<path d="M4 19V5a2 2 0 0 1 2-2h14v18H6a2 2 0 0 1 0-4h14"/>',graduation:'<path d="m2 10 10-5 10 5-10 5-10-5ZM6 12v5c3 3 9 3 12 0v-5M22 10v7"/>',file:'<path d="M7 3h7l5 5v13H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM14 3v6h5M9 13h6M9 17h6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2 2-.1-.1A1.7 1.7 0 0 0 15.8 19a1.7 1.7 0 0 0-1 1.6V21h-3v-.4a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-2-2 .1-.1A1.7 1.7 0 0 0 7 15.4a1.7 1.7 0 0 0-1.6-1H5v-3h.4A1.7 1.7 0 0 0 7 10.4a1.7 1.7 0 0 0-.3-1.9l-.1-.1 2-2 .1.1A1.7 1.7 0 0 0 10.6 7a1.7 1.7 0 0 0 1-1.6V5h3v.4a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 2 2-.1.1A1.7 1.7 0 0 0 19 10.6a1.7 1.7 0 0 0 1.6 1h.4v3h-.4a1.7 1.7 0 0 0-1.2.4Z" transform="translate(-1,-1)"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 18 6-6-6-6"/>',left:'<path d="m15 18-6-6 6-6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',edit:'<path d="m16 4 4 4L9 19H5v-4L16 4Zm-2 2 4 4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',x:'<path d="M5 5 19 19M19 5 5 19"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 21V9m-5 5 5-5 5 5M4 8V3h16v5"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 13h18"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 0 0 18M12 3a15 15 0 0 1 0 18"/>',sparkles:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3ZM19 18l.6 1.4L21 20l-1.4.6L19 22l-.6-1.4L17 20l1.4-.6L19 18Z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',save:'<path d="M4 3h13l3 3v15H4V3Zm3 0v7h10V3M7 21v-8h10v8"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m7 4 13 8-13 8V4Z"/>',rotate:'<path d="M3 11a9 9 0 1 1 3 7M3 4v7h7"/>',filter:'<path d="M4 5h16M7 12h10M10 19h4"/>',bell:'<path d="M18 8a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>'};
function ic(name,size=18){return `<span class="icon" aria-hidden="true"><svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.file}</svg></span>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(){return globalThis.crypto?.randomUUID?.()||('id'+Date.now()+'x'+Math.random().toString(36).slice(2))}
function keyDay(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function atDay(s){if(!s)return new Date();const p=s.slice(0,10).split('-').map(Number);return new Date(p[0],p[1]-1,p[2])}
function addDays(d,n){const t=new Date(d);t.setDate(t.getDate()+n);return t}
function monday(d){const t=atDay(keyDay(d));t.setDate(t.getDate()-(t.getDay()+6)%7);return t}
function monthStart(d){return new Date(d.getFullYear(),d.getMonth(),1)}
function niceDate(d,options={day:'numeric',month:'long',year:'numeric'}){return new Intl.DateTimeFormat('de-DE',options).format(d)}
function shortDate(d){return niceDate(d,{day:'2-digit',month:'short'})}
function daysUntil(s){return Math.ceil((atDay(s)-atDay(keyDay(new Date())))/864e5)}
function mins(t){const p=(t||'00:00').split(':');return (+p[0])*60+(+p[1])}
function clock(d){return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function safeRead(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}}
const saved=safeRead();const state={semester:1,theme:'light',accent:'#6959ec',tasks:[],exams:[],ownEvents:[],notes:{},cards:{},grades:{},completed:{},planning:{},specialization:1,ical:{},studyMinutes:{},...saved};
const ui={week:monday(new Date()),month:monthStart(new Date()),taskFilter:'open',calFilter:'all',noteModule:'',noteView:'edit',cardsIndex:0,cardFlipped:false,focusLen:25,remaining:25*60,focusRunning:false,focusStarted:0,focusModule:'',modalSubmit:null};
const nav=[['heute','Übersicht','home'],['stundenplan','Stundenplan','calendar'],['kalender','Kalender','clock'],['aufgaben','Meine Aufgaben','check'],['pruefungen','Klausuren','file'],['module','Module & Noten','graduation'],['lernzettel','Lernzettel','book'],['fokus','Lern-Timer','target'],['planung','Studienplanung','briefcase'],['einstellungen','Einstellungen','settings']];
const palettes=[['#7866df','#eeeaff','#5744ba'],['#ef8a4d','#fff0e5','#ba5a22'],['#438ed5','#e7f3ff','#256ca7'],['#d76da1','#ffebf4','#a63f73'],['#43a6a1','#e2f7f4','#217d79'],['#b68b3b','#fcf5e2','#916824'],['#8a80c9','#efeefe','#585196'],['#ce756a','#fff0ec','#a85448'],['#5594ad','#e7f5fa','#367287'],['#9a86cd','#f0eafa','#6757a0']];
function palette(s){let h=0;for(const c of String(s||''))h=(h*31+c.charCodeAt(0))|0;let x=palettes[Math.abs(h)%palettes.length];return {color:x[0],bg:x[1],text:x[2],style:`--event-color:${x[0]};--event-bg:${x[1]};--event-text:${x[2]}`}}
function store(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Speicher voll – bitte eine Sicherung exportieren.')}}
function applyTheme(){document.documentElement.dataset.theme=state.theme;document.documentElement.style.setProperty('--accent',state.accent);document.documentElement.style.setProperty('--accent-light',state.accent+'19');$('#themeToggle').innerHTML=ic(state.theme==='dark'?'sun':'moon')}
function moduleId(sem,i){return `${sem}-${i}`}
function modules(sem=state.semester){return (D.semesters[sem]||[]).map((a,i)=>({id:moduleId(sem,i),sem,i,name:a[2]==='specialization'?D.specializations[state.specialization-1]+(sem===4?' I':' II'):a[0],cp:a[1],type:a[2]||'standard'}))}
function allModules(){return Object.keys(D.semesters).flatMap(s=>modules(+s))}
function modName(id){return allModules().find(m=>m.id===id)?.name||'Allgemein'}
function subjectOptions(selected,sem=state.semester){return `<option value="">Kein Fach / Allgemein</option>${modules(sem).map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('')}`}
function completedCP(){return allModules().filter(m=>state.completed[m.id]).reduce((n,m)=>n+m.cp,0)}
function gradeStats(){let a=allModules().filter(m=>Number(state.grades[m.id])>=1&&Number(state.grades[m.id])<=5);let cp=a.reduce((v,m)=>v+m.cp,0);return {grade:cp?(a.reduce((v,m)=>v+Number(state.grades[m.id])*m.cp,0)/cp):null,cp}}
function cleanRoute(){return (location.hash.split('/')[1]||'heute').split('?')[0]}
function title(s){return nav.find(n=>n[0]===s)?.[1]||'Übersicht'}
function toast(s){let e=$('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2900)}
function pageHeading(kicker,name,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function btn(action,label,kind='primary',attrs=''){return `<button type="button" class="button button-${kind}" data-action="${action}" ${attrs}>${label}</button>`}
function heading(title,link='',name='Alle ansehen'){return `<div class="section-top"><h2 class="section-title">${title}</h2>${link?`<a class="link-button" href="#/${link}">${name} ${ic('arrow')}</a>`:''}</div>`}
function empty(icon,head,text,action='',label=''){return `<div class="empty-state"><div class="empty-icon">${ic(icon,24)}</div><strong>${head}</strong><p>${text}</p>${action?btn(action,label,'secondary'):''}</div>`}
function setupNav(){function link([id,label,i]){return `<a class="nav-link" href="#/${id}" data-route="${id}">${ic(i)}<span>${label}</span>${id==='aufgaben'&&state.tasks.some(t=>!t.done)?`<small class="nav-count">${state.tasks.filter(t=>!t.done).length}</small>`:''}</a>`}
 $('#nav').innerHTML=nav.slice(0,7).map(link).join('');$('#navMore').innerHTML=nav.slice(7,9).map(link).join('');$('#mobileNav').innerHTML=[nav[0],nav[1],nav[3],nav[4],nav[6]].map(n=>`<a href="#/${n[0]}" data-route="${n[0]}">${ic(n[2])}<span>${n[1]}</span></a>`).join('');$('#semesterSelect').innerHTML=Array.from({length:7},(_,i)=>`<option value="${i+1}">${i+1}. Semester</option>`).join('');$('#semesterSelect').value=state.semester;let cp=completedCP();$('#sideProgressPct').textContent=Math.round(cp/210*100)+' %';$('#sideProgressFill').style.width=(cp/210*100)+'%';$('#sideProgressLabel').textContent=`${cp} von 210 Credits geschafft`}
function setScreen(html){$('#main').innerHTML=html;$('#crumb').textContent=title(cleanRoute());$('#semesterSelect').value=state.semester;applyTheme();setupNav();document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===cleanRoute()))}
function render(){let route=cleanRoute();let screens={heute:renderHome,stundenplan:renderWeek,kalender:renderMonth,aufgaben:renderTasks,pruefungen:renderExams,module:renderModules,modulee:renderModules,moduleNoten:renderModules,moduleUndNoten:renderModules,moduleGrade:renderModules,module__:renderModules,module2:renderModules,modul:renderModules,modules:renderModules,lernzettel:renderNotes,fokus:renderFocus,planung:renderPlanning,einstellungen:renderSettings};try{setScreen((screens[route]||renderHome)())}catch(e){console.error(e);setScreen(`<div class="card">Die Ansicht konnte nicht geladen werden. ${btn('refresh','Neu laden','secondary')}</div>`)}}
function visibleEvents(){let a=state.ical[state.semester]||[];if(state.semester===1&&a.length===0&&Array.isArray(state.cachedUniversity))a=state.cachedUniversity;return [...a,...state.ownEvents.filter(e=>e.sem===state.semester)]}
function eventDate(e){return new Date(e.start)}
function extraEvents(){return [...state.exams.filter(e=>e.sem===state.semester).map(e=>({id:'exam-'+e.id,kind:'exam',title:'Klausur: '+(e.subject||modName(e.module)),start:e.date+'T'+(e.time||'09:00')+':00',end:e.date+'T'+(e.time||'09:00')+':00',room:e.room||'',module:e.module})),...state.tasks.filter(e=>e.sem===state.semester&&!e.done&&e.due).map(e=>({id:'task-'+e.id,kind:'task',title:'Abgabe: '+e.title,start:e.due+'T23:00:00',end:e.due+'T23:30:00',module:e.module}))]}
function eventsIn(a,b,extra=true){let entries=[...visibleEvents(),...(extra?extraEvents():[])];return entries.filter(e=>{let d=eventDate(e);return d>=a&&d<b}).sort((x,y)=>x.start.localeCompare(y.start))}
function eventColor(e){return e.kind==='exam'?{color:'#e45d77',bg:'#ffedf1',text:'#a0344f',style:'--event-color:#e45d77;--event-bg:#ffedf1;--event-text:#a0344f'}:e.kind==='task'?{color:'#d38e44',bg:'#fff1df',text:'#9a5d2a',style:'--event-color:#d38e44;--event-bg:#fff1df;--event-text:#9a5d2a'}:palette(e.module||e.title)}
function eventRow(e){let d=eventDate(e),p=eventColor(e);return `<div class="agenda-row" style="cursor:pointer" data-action="eventDetails" data-id="${esc(e.id)}"><div class="time-block mono">${clock(d)}<br><span class="muted">${e.kind==='task'?'Frist':e.kind==='exam'?'Prüfung':'Uhr'}</span></div><div class="subject-stripe" style="background:${p.color}"></div><div class="agenda-main"><strong>${esc(e.title)}</strong><small>${esc(e.room||'')}${e.room?' · ':''}${esc(shortDate(d))}</small></div><div class="agenda-arrow">${ic('chevron')}</div></div>`}
function taskRow(t){let p=t.priority;return `<div class="task-row"><button class="task-checkbox ${t.done?'checked':''}" aria-label="Aufgabe ${t.done?'reaktivieren':'abschließen'}" data-action="toggleTask" data-id="${esc(t.id)}">${t.done?ic('check'):''}</button><div class="task-text ${t.done?'done':''}"><strong>${esc(t.title)}</strong><small>${t.due?`Fällig ${esc(niceDate(atDay(t.due),{day:'numeric',month:'short',year:'numeric'}))}`:'Ohne Fälligkeit'} · ${esc(t.module?modName(t.module):'Allgemein')} · <span class="priority ${p}">${p==='high'?'Hoch':p==='medium'?'Mittel':'Niedrig'}</span></small></div><div class="task-actions"><button class="task-action" aria-label="Bearbeiten" data-action="editTask" data-id="${esc(t.id)}">${ic('edit')}</button><button class="task-action" aria-label="Löschen" data-action="deleteTask" data-id="${esc(t.id)}">${ic('trash')}</button></div></div>`}
function renderHome(){const now=new Date(),today=atDay(keyDay(now)),tom=addDays(today,1),todays=eventsIn(today,tom,false),upcoming=eventsIn(tom,addDays(today,8),false).slice(0,3);const open=state.tasks.filter(t=>!t.done&&(t.sem===state.semester||t.sem===0)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));const nextEx=state.exams.filter(e=>e.sem===state.semester&&e.date>=keyDay(today)).sort((a,b)=>a.date.localeCompare(b.date));const done=completedCP(),grades=gradeStats();return `
${pageHeading('DEIN PERSÖNLICHER WORKSPACE','Dein Studium. Im Griff.',`${niceDate(now,{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · Hochschule Aalen`,btn('newTask',`${ic('plus')} Neue Aufgabe`))}
<div class="hero"><div class="hero-content"><div class="hero-kicker">✦ DEIN CAMPUS, DEIN TEMPO</div><h2>Mach aus Plänen<br>echten Fortschritt.</h2><p>Alle Vorlesungen, Aufgaben und Lernziele an einem Ort. Für alle 7 Semester.</p><a class="hero-button" href="#/stundenplan">Wochenstundenplan ansehen ${ic('arrow')}</a></div><div class="hero-orbit one"></div><div class="hero-orbit two"></div><div class="hero-orbit three"></div><div class="hero-planet"></div><div class="hero-star s1">✦</div><div class="hero-star s2">✧</div><div class="hero-star s3">✦</div></div>
<div class="metrics-grid"><div class="card metric"><div class="metric-icon purple">${ic('calendar')}</div><div><div class="metric-number">${todays.length}</div><div class="metric-name">Termine heute</div><div class="metric-extra">${state.semester}. Semester</div></div></div><div class="card metric"><div class="metric-icon orange">${ic('list')}</div><div><div class="metric-number">${open.length}</div><div class="metric-name">Offene Aufgaben</div><div class="metric-extra">${open.filter(t=>t.due&&daysUntil(t.due)<=2).length} bald fällig</div></div></div><div class="card metric"><div class="metric-icon rose">${ic('file')}</div><div><div class="metric-number">${nextEx.length}</div><div class="metric-name">Kommende Prüfungen</div><div class="metric-extra">${nextEx.length?`Nächste in ${daysUntil(nextEx[0].date)} Tagen`:'Keine eingetragen'}</div></div></div><div class="card metric"><div class="metric-icon blue">${ic('graduation')}</div><div><div class="metric-number">${done}<span style="font-size:14px;color:var(--muted)">/210</span></div><div class="metric-name">Credit Points</div><div class="metric-extra">${grades.grade?'Ø Note: '+grades.grade.toFixed(2).replace('.',','):'Noten noch offen'}</div></div></div></div>
<div class="dashboard-grid"><div class="stack"><section class="card">${heading('Heute auf deinem Stundenplan','stundenplan','Zum Stundenplan')}<div class="mini-agenda">${todays.length?todays.map(eventRow).join(''):empty('calendar','Noch keine Termine','Für heute sind im importierten Stundenplan keine Veranstaltungen hinterlegt.','importInfo','Kalender prüfen')}</div></section><section class="card">${heading('Deine nächsten Termine','kalender')}<div class="mini-agenda">${upcoming.length?upcoming.map(eventRow).join(''):empty('clock','Alles ruhig','In den nächsten Tagen sind keine weiteren Vorlesungen eingetragen.')}</div></section></div><div class="stack"><section class="card">${heading('Offene Aufgaben','aufgaben')}<div>${open.length?open.slice(0,5).map(taskRow).join(''):empty('check','Alles erledigt!','Hier findest du demnächst deine Abgaben und Aufgaben.','newTask','Aufgabe erstellen')}</div></section><section class="card">${heading('Klausuren im Blick','pruefungen')}<div>${nextEx.length?nextEx.slice(0,3).map(e=>`<div class="agenda-row"><div class="time-block">${daysUntil(e.date)}<br><span class="muted">Tage</span></div><div class="subject-stripe" style="background:#e76f8d"></div><div class="agenda-main"><strong>${esc(e.subject||modName(e.module))}</strong><small>${esc(niceDate(atDay(e.date)))} ${e.time?'· '+esc(e.time):''}</small></div></div>`).join(''):empty('file','Keine Klausuren eingetragen','Trage deine offiziellen Klausurtermine ein.','newExam','Klausur eintragen')}</div></section></div></div>`}
function weekLabel(d){return `${shortDate(d)} – ${shortDate(addDays(d,5))} ${addDays(d,5).getFullYear()}`}
function renderWeek(){const days=Array.from({length:6},(_,i)=>addDays(ui.week,i));const startH=7,endH=23,hour=70;const begin=atDay(keyDay(ui.week)),end=addDays(begin,6);const events=eventsIn(begin,end,false);const blocks=(i)=>{let day=days[i],dayEv=events.filter(e=>keyDay(eventDate(e))===keyDay(day)).sort((a,b)=>a.start.localeCompare(b.start));return dayEv.map((e,j)=>{let d=eventDate(e),b=new Date(e.end||e.start),startMin=Math.max(startH*60,d.getHours()*60+d.getMinutes()),endMin=Math.min(endH*60,Math.max(startMin+25,b.getHours()*60+b.getMinutes())),top=Math.max(0,(startMin-startH*60)/60*hour),height=Math.max(28,(endMin-startMin)/60*hour-3),p=eventColor(e);let overlapping=dayEv.filter((x,k)=>k<j&&eventDate(x)<b&&new Date(x.end||x.start)>d).length;return `<button type="button" class="cal-event" data-action="eventDetails" data-id="${esc(e.id)}" title="${esc(e.title)}" style="${p.style};top:${top}px;height:${height}px;${overlapping?'left:'+Math.min(28,4+overlapping*14)+'px;':''}"><strong>${esc(e.title)}</strong><span>${esc(clock(d))}–${esc(clock(b))}</span>${e.room?`<span class="cal-event-room">${esc(e.room)}</span>`:''}</button>`}).join('')};return `${pageHeading('WOCHENÜBERSICHT','Dein Stundenplan',`Echte Zeitblöcke aus dem sPlan der Hochschule Aalen · ${state.semester}. Semester`,btn('newEvent',`${ic('plus')} Eigener Termin`))}<div class="toolbar" style="margin-bottom:17px"><div class="toolbar-left"><div class="calendar-arrows">${btn('prevWeek',ic('left'),'secondary')}${btn('nextWeek',ic('chevron'),'secondary')}</div><strong class="mono">${esc(weekLabel(ui.week))}</strong>${btn('todayWeek','Heute','ghost')}</div><div class="toolbar-right">${btn('importInfo',`${ic('rotate')} Stundenplan laden`,'secondary')}</div></div>${state.semester>1&&!state.ical[state.semester]?.length?`<div class="banner-info" style="margin-bottom:17px">Für Semester ${state.semester} ist noch kein Hochschul-Stundenplan hinterlegt. Importiere deine neue iCal-Datei in den Einstellungen. Eigene Termine funktionieren bereits.</div>`:''}${state.semester===1&&!state.ical[1]?.length&&!state.cachedUniversity?.length?`<div class="banner-info" style="margin-bottom:17px">Der sPlan wird geladen. Falls keine Vorlesungen erscheinen, kannst du unter Einstellungen eine iCal-Datei importieren.</div>`:''}<div class="week-wrap"><div class="week-grid"><div class="week-head">Uhrzeit</div>${days.map(d=>`<div class="week-head ${keyDay(d)===keyDay(new Date())?'today':''}">${esc(niceDate(d,{weekday:'short'}))}<span class="day-num">${d.getDate()}</span></div>`).join('')}<div class="week-time-column" style="height:${(endH-startH)*hour}px">${Array.from({length:endH-startH},(_,i)=>`<span class="time-tick" style="top:${i*hour+1}px">${String(startH+i).padStart(2,'0')}:00</span>`).join('')}</div>${days.map((d,i)=>`<div class="week-day-column" style="height:${(endH-startH)*hour}px">${blocks(i)}</div>`).join('')}</div></div><div class="week-legend" style="display:flex;gap:14px;flex-wrap:wrap;margin-top:16px"><span class="small muted">Farben unterscheiden Veranstaltungen. Klicke auf einen Block für Details.</span><span class="small muted">${events.length} Einträge diese Woche</span></div>`}
function renderMonth(){let y=ui.month.getFullYear(),m=ui.month.getMonth();let first=monthStart(ui.month),gridStart=monday(first),cells=Array.from({length:42},(_,i)=>addDays(gridStart,i)),end=addDays(gridStart,42),events=eventsIn(gridStart,end,true);let view=(d)=>events.filter(e=>keyDay(eventDate(e))===keyDay(d));let upcoming=eventsIn(atDay(keyDay(new Date())),addDays(new Date(),31),true).slice(0,16);return `${pageHeading('DEIN KALENDER','Alle Termine. Ein Überblick.','Vorlesungen, Prüfungen, Fristen und deine eigenen Termine.',btn('newEvent',`${ic('plus')} Termin erstellen`))}<div class="toolbar" style="margin-bottom:16px"><div class="toolbar-left"><div class="calendar-arrows">${btn('prevMonth',ic('left'),'secondary')}${btn('nextMonth',ic('chevron'),'secondary')}</div><strong>${esc(niceDate(first,{month:'long',year:'numeric'}))}</strong>${btn('todayMonth','Heute','ghost')}</div><div class="toolbar-right">${btn('exportCalendar',`${ic('download')} Kalender exportieren`,'secondary')}</div></div><div class="month-grid">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(s=>`<div class="month-day-name">${s}</div>`).join('')}${cells.map(d=>{let dayItems=view(d),current=d.getMonth()===m;return `<div class="month-cell ${current?'':'outside'}" data-action="dayDetails" data-date="${keyDay(d)}"><div class="month-number" ${keyDay(d)===keyDay(new Date())?'style="background:var(--accent);color:white;border-radius:7px;padding:3px 6px"':''}>${d.getDate()}</div>${dayItems.slice(0,3).map(e=>`<div class="month-dot" style="${eventColor(e).style};background:var(--event-bg);border-left:3px solid var(--event-color);color:var(--event-text)">${esc(e.title)}</div>`).join('')}${dayItems.length>3?`<small class="month-more">+${dayItems.length-3} mehr</small>`:''}</div>`}).join('')}</div><section style="margin-top:27px">${heading('Die nächsten 30 Tage')}<div class="event-list">${upcoming.length?upcoming.map(e=>`<div class="event-list-row" data-action="eventDetails" data-id="${esc(e.id)}" style="cursor:pointer"><div class="event-date-tile"><strong>${eventDate(e).getDate()}</strong><small>${esc(niceDate(eventDate(e),{month:'short'}))}</small></div><div class="event-list-main"><strong>${esc(e.title)}</strong><small>${esc(niceDate(eventDate(e),{weekday:'short'}))}, ${esc(clock(eventDate(e)))}${e.room?' · '+esc(e.room):''}</small></div><div class="subject-stripe" style="background:${eventColor(e).color};height:36px"></div></div>`).join(''):empty('calendar','Keine Termine','Es sind keine weiteren Einträge hinterlegt.')}</div></section>`}
function renderTasks(){const list=state.tasks.filter(t=>t.sem===state.semester||t.sem===0).filter(t=>ui.taskFilter==='all'||(ui.taskFilter==='done'?t.done:!t.done)).sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')||({high:0,medium:1,low:2}[a.priority]-{high:0,medium:1,low:2}[b.priority]));return `${pageHeading('AUFGABENMANAGER','Deine To-dos',`Prioritäten setzen und Abgaben rechtzeitig erledigen.`,btn('newTask',`${ic('plus')} Neue Aufgabe`))}<div class="card"><div class="toolbar" style="margin-bottom:15px"><div class="segmented">${[['open','Offen'],['all','Alle'],['done','Erledigt']].map(a=>`<button class="segment ${ui.taskFilter===a[0]?'active':''}" data-action="taskFilter" data-value="${a[0]}">${a[1]}</button>`).join('')}</div><span class="small muted">${list.length} Aufgaben</span></div><div class="task-list-full">${list.length?list.map(taskRow).join(''):empty('check','Hier ist alles frei','Erstelle eine neue Aufgabe oder wechsle den Filter.','newTask','Aufgabe erstellen')}</div></div>`}
function renderExams(){let a=state.exams.filter(x=>x.sem===state.semester).sort((a,b)=>a.date.localeCompare(b.date));return `${pageHeading('KLAUSURPHASE','Dein Klausurenplan','Termine, Countdown, Anmeldung und Hilfsmittel auf einen Blick.',btn('newExam',`${ic('plus')} Klausur eintragen`))}<div class="banner-info" style="margin-bottom:20px">Prüfungstermine sind bewusst nicht vorausgefüllt. Bitte übertrage sie aus dem offiziellen Prüfungsplan deiner Hochschule.</div><div class="cards-grid">${a.length?a.map(e=>{let d=atDay(e.date),diff=daysUntil(e.date);return `<article class="exam-card"><div class="exam-date"><strong>${d.getDate()}</strong><span>${esc(niceDate(d,{month:'short',year:'numeric'}))}</span></div><div class="exam-main"><h3>${esc(e.subject||modName(e.module))}</h3><p>${esc(niceDate(d,{weekday:'long'}))}${e.time?' · '+esc(e.time)+' Uhr':''} ${e.room?' · Raum '+esc(e.room):''}</p><div class="exam-meta"><span class="status-tag ${e.registered?'registered':'pending'}">${e.registered?'✓ Angemeldet':'Anmeldung prüfen'}</span>${e.aids?`<span class="status-tag">${esc(e.aids)}</span>`:''}</div>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div><div class="exam-right"><div class="countdown">${diff<0?'Vergangen':diff===0?'Heute':`Noch ${diff} Tage`}</div><div class="task-actions"><button class="task-action" data-action="editExam" data-id="${esc(e.id)}" aria-label="Klausur bearbeiten">${ic('edit')}</button><button class="task-action" data-action="deleteExam" data-id="${esc(e.id)}" aria-label="Klausur löschen">${ic('trash')}</button></div></div></article>`}).join(''):empty('file','Noch keine Klausuren eingetragen','Trage deine bestätigten Prüfungstermine ein.','newExam','Erste Klausur eintragen')}</div>`}
function renderModules(){let all=allModules(),sem=modules(),taken=all.filter(m=>state.completed[m.id]),cps=taken.reduce((n,m)=>n+m.cp,0),g=gradeStats(),semCP=sem.reduce((n,m)=>n+m.cp,0);return `${pageHeading('STUDIENFORTSCHRITT','Module & Noten','Dein Curriculum, deine Credits und deine Leistungen.')}${state.semester===4||state.semester===6?`<div class="specialization-pick"><span class="small muted">Gewählter Schwerpunkt:</span><select class="select" data-action="specialization" id="specialization">${D.specializations.map((s,i)=>`<option value="${i+1}" ${state.specialization===i+1?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`:''}<div class="modules-header"><div><div class="eyebrow" style="color:#bfc5fa">SEMESTER ${state.semester} VON 7</div><h2>${state.semester===5?'Dein Praxissemester':`${state.semester}. Semester`}</h2><p>${sem.length} Module · ${semCP} CP vorgesehen · ${sem.filter(m=>state.completed[m.id]).reduce((a,m)=>a+m.cp,0)} CP abgeschlossen</p></div><div style="text-align:right"><div class="modules-counter">${cps}<span style="font-size:14px;color:#b7bdea"> / 210</span></div><p style="color:#b7bdea;font-size:11px">Credits insgesamt</p></div></div><div class="metrics-grid"><div class="card metric"><div class="metric-icon blue">${ic('graduation')}</div><div><div class="metric-number">${cps}</div><div class="metric-name">Gesammelte CP</div></div></div><div class="card metric"><div class="metric-icon purple">${ic('check')}</div><div><div class="metric-number">${taken.length}</div><div class="metric-name">Abgeschlossene Module</div></div></div><div class="card metric"><div class="metric-icon orange">${ic('target')}</div><div><div class="metric-number">${g.grade?g.grade.toFixed(2).replace('.',','):'–'}</div><div class="metric-name">Gewichteter Notenschnitt</div></div></div><div class="card metric"><div class="metric-icon rose">${ic('clock')}</div><div><div class="metric-number">${210-cps}</div><div class="metric-name">Verbleibende CP</div></div></div></div><div class="module-grid">${sem.map((m,i)=>{let grade=state.grades[m.id]||'',p=palette(m.name);return `<article class="module-card" style="border-top:3px solid ${p.color}"><div class="module-head"><span class="module-index">MODUL ${String(i+1).padStart(2,'0')}</span><span class="cp-bubble">${m.cp} CP</span></div><h3>${esc(m.name)}</h3><div class="module-bottom"><select class="grade-input" data-action="grade" data-id="${m.id}" aria-label="Note ${esc(m.name)}"><option value="">Note –</option>${['1.0','1.3','1.7','2.0','2.3','2.7','3.0','3.3','3.7','4.0','5.0'].map(v=>`<option value="${v}" ${v===grade?'selected':''}>${v.replace('.',',')}</option>`).join('')}</select><label class="module-status"><input type="checkbox" data-action="moduleDone" data-id="${m.id}" ${state.completed[m.id]?'checked':''}> Bestanden</label></div><button class="module-open-notes" data-action="openNote" data-id="${m.id}">${ic('book')} Lernzettel öffnen ${ic('arrow')}</button></article>`}).join('')}</div><p class="settings-note">Hinweis: Die Schwerpunkt-Module im 4. und 6. Semester sind Wahlmöglichkeiten, keine vier gleichzeitig verpflichtenden Fächer. Die Note berechnet sich CP-gewichtet aus allen von dir eingetragenen Noten; deine offizielle Prüfungsordnung kann abweichende Regeln vorsehen.</p>`}
function markdown(v){return esc(v||'').replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/^[-*] (.*)$/gm,'• $1').replace(/\n/g,'<br>')}
function renderNotes(){let list=modules(),sel=list.find(m=>m.id===ui.noteModule)||list[0];if(!sel)return empty('book','Keine Module','');ui.noteModule=sel.id;let cards=state.cards[sel.id]||[],p=palette(sel.name);return `${pageHeading('DEINE LERNBIBLIOTHEK','Lernzettel & Karteikarten','Für jedes Fach ein eigener Platz zum Mitschreiben und Lernen.',btn('printNote',`${ic('download')} Als PDF drucken`,'secondary'))}<div class="notes-layout"><div class="card notes-sidebar">${list.map(m=>{let pal=palette(m.name);return `<button class="notes-subject ${sel.id===m.id?'active':''}" data-action="selectNote" data-id="${m.id}" title="${esc(m.name)}" style="${pal.style}"><span class="notes-avatar">${esc(m.name.slice(0,2).toUpperCase())}</span><span>${esc(m.name)}</span><span class="notes-count">${(state.cards[m.id]||[]).length}</span></button>`}).join('')}</div><div class="card notes-editor"><div class="eyebrow">${state.semester}. SEMESTER · ${sel.cp} CP</div><h2 class="notes-title">${esc(sel.name)}</h2><div class="notes-toolbar"><div class="segmented"><button class="segment ${ui.noteView==='edit'?'active':''}" data-action="noteMode" data-value="edit">Schreiben</button><button class="segment ${ui.noteView==='preview'?'active':''}" data-action="noteMode" data-value="preview">Vorschau</button><button class="segment ${ui.noteView==='cards'?'active':''}" data-action="noteMode" data-value="cards">Karteikarten (${cards.length})</button></div><span class="note-save">${ic('save')} Automatisch gespeichert</span></div>${ui.noteView==='edit'?`<textarea class="note-textarea" id="noteInput" data-action="noteInput" placeholder="# ${esc(sel.name)}\n\n## Vorlesung 1\n- Deine wichtigsten Erkenntnisse\n- Formeln und Definitionen\n\n## Prüfungsfragen\n...">${esc(state.notes[sel.id]||'')}</textarea><div class="settings-note">Tipp: Mit #, ##, - und **fett** kannst du deine Notizen strukturieren. Speichert sich beim Tippen.</div>`:ui.noteView==='preview'?`<div class="note-preview">${state.notes[sel.id]?markdown(state.notes[sel.id]):'<span class="muted">Dein Lernzettel ist noch leer. Wechsle zu „Schreiben“ und leg los.</span>'}</div>`:`${cards.length?`<div class="eyebrow">KARTE ${Math.min(ui.cardsIndex+1,cards.length)} VON ${cards.length}</div><div class="flashcard ${ui.cardFlipped?'flipped':''}" data-action="flipCard" role="button" tabindex="0">${esc(cards[Math.min(ui.cardsIndex,cards.length-1)][ui.cardFlipped?'answer':'question'])}<div style="font-size:10px;position:absolute;margin-top:125px;opacity:.6">Klicken zum Umdrehen</div></div><div class="focus-controls">${btn('prevCard',ic('left'),'secondary')}${btn('nextCard',ic('chevron'),'secondary')}</div>`:empty('book','Noch keine Karteikarten','Fragen und Antworten helfen dir beim Wiederholen.')}<div style="margin:20px 0">${btn('newCard',`${ic('plus')} Karteikarte hinzufügen`)}</div><div class="flashcard-list">${cards.map((c,i)=>`<div class="flashcard-item"><div><strong>${esc(c.question)}</strong><small>${esc(c.answer)}</small></div><button class="task-action" data-action="deleteCard" data-id="${esc(c.id)}" aria-label="Karte löschen">${ic('trash')}</button></div>`).join('')}</div>`}</div></div>`}
function renderFocus(){let total=ui.focusLen*60,progress=(total-ui.remaining)/total*100;return `${pageHeading('FOKUSMODUS','Zeit für Deep Work.','Lerne ohne Ablenkung – dein Fortschritt zählt.',btn('resetFocus',`${ic('rotate')} Zurücksetzen`,'secondary'))}<div class="focus-grid"><div class="card focus-main"><div class="eyebrow">POMODORO FOKUS-TIMER</div><div class="focus-circle" style="--focus-progress:${progress}%"><div><div class="focus-time" id="timerTime">${fmtTime(ui.remaining)}</div><div class="focus-sub">${ui.focusRunning?'Konzentriert bleiben.':'Bereit für deine nächste Session?'}</div></div></div><div class="focus-controls">${btn('toggleFocus',`${ic(ui.focusRunning?'pause':'play')} ${ui.focusRunning?'Pause':'Starten'}`)}${btn('resetFocus',`${ic('rotate')} Reset`,'secondary')}</div><div class="focus-durations">${[15,25,45,60].map(m=>`<button class="${ui.focusLen===m?'active':''}" data-action="focusDuration" data-value="${m}">${m} min</button>`).join('')}</div></div><div class="card"><h3 class="section-title">Dein Lernziel</h3><p class="subtle">Wähle das Fach, für das du lernen möchtest.</p><select id="focusSubject" class="select" style="width:100%" data-action="focusSubject"><option value="">Allgemeine Lernzeit</option>${modules().map(m=>`<option value="${m.id}" ${ui.focusModule===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><div class="settings-divider"></div><h3 class="section-title">Gesammelte Lernzeit</h3>${modules().filter(m=>state.studyMinutes[m.id]).map(m=>`<div class="planning-step"><span>${esc(m.name)}</span><strong style="margin-left:auto">${Math.round(state.studyMinutes[m.id])} min</strong></div>`).join('')||'<p class="subtle">Sobald du eine Fokus-Session beendest, erscheint sie hier.</p>'}<div class="banner-info" style="margin-top:15px">Der Timer bleibt aktiv, solange diese Webseite geöffnet ist. Bei Pausen oder Tabwechseln wird die verstrichene Zeit berücksichtigt.</div></div></div>`}
function fmtTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`}
function renderPlanning(){return `${pageHeading('DEIN FAHRPLAN','Die nächsten Meilensteine.','Praxissemester, Ausland und Bachelorarbeit Schritt für Schritt vorbereiten.')}<div class="planning-grid">${D.planning.map(p=>{let checked=state.planning[p.id]||[],done=p.steps.filter((_,i)=>checked.includes(i)).length;return `<article class="card planning-card"><div class="planning-icon">${ic(p.icon,23)}</div><h3>${p.title}</h3><div class="plan-desc">${p.desc}</div>${p.steps.map((s,i)=>`<label class="planning-step ${checked.includes(i)?'done':''}"><input type="checkbox" data-action="planStep" data-group="${p.id}" data-index="${i}" ${checked.includes(i)?'checked':''}><span>${esc(s)}</span></label>`).join('')}<div class="planning-footer">${done} / ${p.steps.length} erledigt</div></article>`}).join('')}</div><p class="settings-note">Die Listen sind Planungshilfen, keine amtlichen Zulassungs- oder Bewerbungsfristen. Informiere dich rechtzeitig bei der Hochschule Aalen.</p>`}
function renderSettings(){const acc=[['#6959ec','Violett'],['#3f7ce0','Kobaltblau'],['#e86a72','Koralle'],['#b35cc4','Orchidee'],['#2e939a','Petrol']];return `${pageHeading('DEIN WORKSPACE','Einstellungen','Aussehen, Stundenplan und deine persönlichen Daten verwalten.')}<div class="settings-layout"><section class="card settings-section"><h3>Dein Design</h3><p>Wähle deine Lieblingsfarbe und zwischen einem hellen und dunklen Arbeitsbereich.</p><div class="accent-picker">${acc.map(a=>`<button type="button" title="${a[1]}" aria-label="Farbe ${a[1]}" class="accent-swatch ${state.accent===a[0]?'active':''}" style="--swatch:${a[0]}" data-action="accent" data-value="${a[0]}"></button>`).join('')}</div><div class="settings-divider"></div><div class="theme-options"><button class="theme-option ${state.theme==='light'?'active':''}" data-action="setTheme" data-value="light">☀ Hell</button><button class="theme-option ${state.theme==='dark'?'active':''}" data-action="setTheme" data-value="dark">☾ Dunkel</button></div></section><section class="card settings-section"><h3>Stundenplan der Hochschule</h3><p>Das 1. Semester wird mit dem iCal-Stundenplan der Hochschule Aalen verbunden. Für spätere Semester lädst du deine neue iCal-Datei hier hoch.</p><div class="settings-action">${btn('reloadICS',`${ic('rotate')} Aktualisieren`,'secondary')}${btn('importICS',`${ic('upload')} iCal-Datei laden`)}</div><input type="file" id="icsFile" class="file-input" accept=".ics,text/calendar"><div class="settings-note">Status: <strong>${(state.ical[state.semester]||[]).length} Veranstaltungen für Semester ${state.semester} gespeichert</strong>. Die Daten sind auch ohne Verbindung nutzbar, nachdem sie geladen wurden.</div><div class="settings-note"><a href="${esc(D.icalURL)}" target="_blank" rel="noopener noreferrer" class="link-button">Offiziellen sPlan öffnen ${ic('arrow')}</a></div></section><section class="card settings-section"><h3>Backup deiner Daten</h3><p>Deine Aufgaben, Lernzettel und Noten liegen lokal in diesem Browser. Exportiere eine Sicherung für andere Geräte oder als Backup.</p><div class="settings-action">${btn('exportBackup',`${ic('download')} Sicherung exportieren`)}${btn('importBackup',`${ic('upload')} Sicherung importieren`,'secondary')}</div><input type="file" id="backupFile" class="file-input" accept="application/json,.json"><div class="settings-note">Wichtig: Es gibt keine automatische Synchronisierung zwischen Geräten. Lade deine Sicherungsdatei auf dem anderen Gerät wieder hoch.</div></section><section class="card settings-section"><h3>Kalender mitnehmen</h3><p>Exportiere deine selbst erstellten Termine, Prüfungen und Aufgaben als iCal-Datei zum Einbinden in Apple Kalender, Google Kalender oder Outlook.</p><div class="settings-action">${btn('exportCalendar',`${ic('calendar')} Eigene Termine als .ics`,'secondary')}</div><div class="settings-divider"></div><h3>Daten zurücksetzen</h3><p>Entfernt alle lokalen Eingaben aus diesem Browser. Erstelle vorher eine Sicherung.</p>${btn('resetAll',`${ic('trash')} Alle Daten löschen`,'red')}</section></div>`}
function field(label,name,type='text',value='',attrs=''){return `<label class="field"><span>${label}</span><input class="text-input" type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`}
function selectField(label,name,items,selected){return `<label class="field"><span>${label}</span><select class="select" name="${name}">${items.map(a=>`<option value="${esc(a[0])}" ${String(a[0])===String(selected)?'selected':''}>${esc(a[1])}</option>`).join('')}</select></label>`}
function modal(title,eyebrow,content,cb){ui.modalSubmit=cb;$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=content;$('#modal').showModal()}
function openTask(id){let t=state.tasks.find(x=>x.id===id)||{id:uid(),title:'',due:'',priority:'medium',module:'',sem:state.semester,notes:'',done:false};modal(id?'Aufgabe bearbeiten':'Neue Aufgabe','TODO',`${field('Was steht an?','title','text',t.title,'required maxlength="180" placeholder="z. B. Marketing Case vorbereiten"')}<div class="field-grid">${field('Fällig am','due','date',t.due)}${selectField('Priorität','priority',[['high','Hoch'],['medium','Mittel'],['low','Niedrig']],t.priority)}</div>${selectField('Fach','module',[['','Allgemein'],...modules(t.sem).map(m=>[m.id,m.name])],t.module)}<label class="field"><span>Notiz (optional)</span><textarea class="text-input" name="notes" rows="3">${esc(t.notes)}</textarea></label>`,fd=>{let z=Object.fromEntries(fd);if(!z.title?.trim())return false;Object.assign(t,{title:z.title.trim(),due:z.due||'',priority:z.priority,module:z.module,notes:z.notes||'',sem:t.sem});if(!id)state.tasks.push(t);store();toast('Aufgabe gespeichert');return true})}
function openExam(id){let e=state.exams.find(x=>x.id===id)||{id:uid(),sem:state.semester,subject:'',module:'',date:'',time:'',room:'',aids:'',notes:'',registered:false};modal(id?'Klausur bearbeiten':'Klausur eintragen','PRÜFUNG',`${field('Klausur / Bezeichnung','subject','text',e.subject,'required maxlength="180"')}<div class="field-grid">${field('Datum','date','date',e.date,'required')}${field('Uhrzeit','time','time',e.time)}</div><div class="field-grid">${field('Raum','room','text',e.room)}${field('Hilfsmittel','aids','text',e.aids)}</div>${selectField('Fach','module',[['','Keins ausgewählt'],...modules(e.sem).map(m=>[m.id,m.name])],e.module)}<label class="field"><span>Weitere Informationen</span><textarea name="notes" class="text-input" rows="2">${esc(e.notes)}</textarea></label><label class="planning-step"><input type="checkbox" name="registered" ${e.registered?'checked':''}><span>Zur Klausur angemeldet</span></label>`,fd=>{let z=Object.fromEntries(fd);if(!z.date||!z.subject.trim())return false;Object.assign(e,{...z,subject:z.subject.trim(),registered:z.registered==='on'});if(!id)state.exams.push(e);store();toast('Klausur gespeichert');return true})}
function openEvent(id,date){let e=state.ownEvents.find(x=>x.id===id)||{id:uid(),sem:state.semester,title:'',start:(date||keyDay(new Date()))+'T12:00:00',end:(date||keyDay(new Date()))+'T13:00:00',room:'',module:'',kind:'own'};modal(id?'Termin bearbeiten':'Termin erstellen','KALENDER',`${field('Bezeichnung','title','text',e.title,'required maxlength="180"')}<div class="field-grid">${field('Datum','date','date',e.start.slice(0,10),'required')}${field('Start','start','time',e.start.slice(11,16),'required')}</div><div class="field-grid">${field('Ende','end','time',e.end.slice(11,16),'required')}${field('Ort','room','text',e.room)}</div>${selectField('Fach (optional)','module',[['','Allgemein'],...modules(e.sem).map(m=>[m.id,m.name])],e.module)}`,fd=>{let z=Object.fromEntries(fd);if(!z.title.trim()||!z.date||mins(z.end)<=mins(z.start)){toast('Bitte gültigen Zeitraum eingeben.');return false}Object.assign(e,{title:z.title.trim(),start:z.date+'T'+z.start+':00',end:z.date+'T'+z.end+':00',room:z.room,module:z.module});if(!id)state.ownEvents.push(e);store();toast('Termin gespeichert');return true})}
function openCard(){let id=ui.noteModule;modal('Neue Karteikarte','LERNKARTE',`<label class="field"><span>Frage</span><textarea name="question" class="text-input" rows="3" required placeholder="Was bedeutet ...?"></textarea></label><label class="field"><span>Antwort</span><textarea name="answer" class="text-input" rows="4" required></textarea></label>`,fd=>{let z=Object.fromEntries(fd);if(!z.question.trim()||!z.answer.trim())return false;(state.cards[id]??=[]).push({id:uid(),question:z.question.trim(),answer:z.answer.trim()});ui.cardFlipped=false;ui.cardsIndex=(state.cards[id].length-1);store();toast('Karteikarte gespeichert');return true})}
function details(e){if(e.kind==='own'){modal('Termin','DEIN KALENDER',`<p><strong>${esc(e.title)}</strong></p><p>${esc(niceDate(eventDate(e)))} · ${esc(clock(eventDate(e)))} Uhr</p><p>${esc(e.room||'Ohne Ort')}</p>${btn('editOwnInModal',`${ic('edit')} Bearbeiten`,'secondary',`data-id="${esc(e.id)}"`)}`,()=>true);return}modal('Termindetails','STUNDENPLAN',`<h3>${esc(e.title)}</h3><p class="subtle">${esc(niceDate(eventDate(e),{weekday:'long',day:'numeric',month:'long',year:'numeric'}))} · ${esc(clock(eventDate(e)))} Uhr</p><p>${e.room?`Raum: ${esc(e.room)}`:'Ohne Ortsangabe'}</p><p class="settings-note">Quelle: ${e.kind==='university'?'sPlan der Hochschule Aalen':e.kind==='exam'?'Dein Klausurenplan':'Deine Aufgaben'}</p>`,()=>true)}
function download(filename,text,mime='text/plain'){let url=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function exportBackup(){download('orbit-studioplaner-backup-'+keyDay(new Date())+'.json',JSON.stringify({version:2,created:new Date().toISOString(),state},null,2),'application/json');toast('Sicherung heruntergeladen')}
function calendarExport(){let e=[...state.ownEvents,...state.exams.map(x=>({id:'exam-'+x.id,title:'Klausur: '+(x.subject||modName(x.module)),start:x.date+'T'+(x.time||'09:00')+':00',end:x.date+'T'+(x.time||'09:00')+':00',room:x.room||''})),...state.tasks.filter(x=>!x.done&&x.due).map(x=>({id:'task-'+x.id,title:'Abgabe: '+x.title,start:x.due+'T23:00:00',end:x.due+'T23:30:00',room:''}))];if(!e.length){toast('Noch keine eigenen Termine eingetragen');return}function utc(t){return new Date(t).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z'}function sani(s){return String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')};let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//orbit//IBW Studium//DE','CALSCALE:GREGORIAN',...e.flatMap((x,i)=>['BEGIN:VEVENT',`UID:${sani(x.id||i)}@orbit-ibw`,`DTSTAMP:${utc(new Date().toISOString())}`,`DTSTART:${utc(x.start)}`,`DTEND:${utc(x.end||x.start)}`,`SUMMARY:${sani(x.title)}`,`LOCATION:${sani(x.room||'')}`,'END:VEVENT']),'END:VCALENDAR'];download('orbit-meine-termine.ics',lines.join('\r\n'),'text/calendar');toast('Kalenderdatei heruntergeladen')}
function parseICS(raw){const t=String(raw||'').replace(/\r\n[ \t]/g,'').replace(/\n[ \t]/g,'');let blocks=t.match(/BEGIN:VEVENT[\s\S]*?END:VEVENT/g)||[];return blocks.map((block,i)=>{let v={};block.split(/\r?\n/).forEach(line=>{let pos=line.indexOf(':');if(pos>0){let k=line.slice(0,pos).split(';')[0].toUpperCase(),val=line.slice(pos+1);v[k]=val}});if(!v.DTSTART||!v.SUMMARY)return null;const parse=(s)=>{let z=s.replace(/Z$/,'');if(/^\d{8}T\d{4}/.test(z))return `${z.slice(0,4)}-${z.slice(4,6)}-${z.slice(6,8)}T${z.slice(9,11)}:${z.slice(11,13)}:${z.slice(13,15)||'00'}`;if(/^\d{8}$/.test(z))return `${z.slice(0,4)}-${z.slice(4,6)}-${z.slice(6,8)}T00:00:00`;return ''};let st=parse(v.DTSTART),en=parse(v.DTEND||v.DTSTART);if(!st)return null;let name=v.SUMMARY.replace(/\\,/g,',').replace(/\\n/ig,' ').replace(/\\;/g,';').replace(/\s*\(\d+-\d+\)\s*$/,'').trim();return {id:'uni-'+(v.UID||i)+'-'+st,title:name,start:st,end:en||st,room:(v.LOCATION||'').replace(/\\,/g,',').replace(/\\n/g,' '),kind:'university',module:''}}).filter(Boolean).sort((a,b)=>a.start.localeCompare(b.start))}
async function reloadICS(force=false){if(state.semester!==1){toast('Für Semester '+state.semester+' eine .ics-Datei importieren.');$('#icsFile')?.click();return}let urls=['data/stundenplan.ics','https://raw.githubusercontent.com/Kiyo0711/ibw-studium/main/data/stundenplan-1.ics'];for(let url of urls){try{let res=await fetch(url,{cache:force?'no-store':'default'});if(!res.ok)continue;let txt=await res.text();let parsed=parseICS(txt);if(parsed.length){state.ical[1]=parsed;store();render();toast(`${parsed.length} Hochschultermine geladen`);return}}catch(err){console.warn('Kalenderquelle nicht verfügbar:',url)}}toast('Kalender konnte nicht automatisch geladen werden. Bitte .ics-Datei importieren.')}
function fileRead(id,cb){let el=document.getElementById(id);if(!el)return;el.onchange=async()=>{let f=el.files?.[0];if(!f)return;try{await cb(await f.text())}catch(e){toast('Datei konnte nicht gelesen werden');console.error(e)}el.value=''};el.click()}
function updateFocus(){if(!ui.focusRunning)return;let elapsed=Math.floor((Date.now()-ui.focusStarted)/1000);if(elapsed<=0)return;ui.focusStarted=Date.now();ui.remaining=Math.max(0,ui.remaining-elapsed);let el=$('#timerTime');if(el){el.textContent=fmtTime(ui.remaining);let circle=$('.focus-circle');if(circle)circle.style.setProperty('--focus-progress',((ui.focusLen*60-ui.remaining)/(ui.focusLen*60)*100)+'%')}if(ui.remaining===0){ui.focusRunning=false;state.studyMinutes[ui.focusModule||'general']=(state.studyMinutes[ui.focusModule||'general']||0)+ui.focusLen;store();render();toast('Fokus-Session abgeschlossen! Super gemacht.');if('Notification'in window&&Notification.permission==='granted')new Notification('Orbit: Session geschafft!',{body:'Zeit für eine Pause.'})}}
function closeMenu(){$('#sidebar').classList.remove('open');$('#mobileBackdrop').hidden=true}
const act={
 newTask:()=>openTask(),editTask:e=>openTask(e.dataset.id),deleteTask:e=>{if(confirm('Diese Aufgabe löschen?')){state.tasks=state.tasks.filter(x=>x.id!==e.dataset.id);store();render()}},toggleTask:e=>{let t=state.tasks.find(x=>x.id===e.dataset.id);if(t){t.done=!t.done;store();render()}},taskFilter:e=>{ui.taskFilter=e.dataset.value;render()},
 newExam:()=>openExam(),editExam:e=>openExam(e.dataset.id),deleteExam:e=>{if(confirm('Klausur löschen?')){state.exams=state.exams.filter(x=>x.id!==e.dataset.id);store();render()}},
 newEvent:()=>openEvent(),eventDetails:e=>{let id=e.dataset.id,x=[...visibleEvents(),...extraEvents()].find(z=>z.id===id);if(x)details(x)},dayDetails:e=>{let day=atDay(e.dataset.date);let a=eventsIn(day,addDays(day,1));modal(niceDate(day),'TAGESÜBERSICHT',a.length?a.map(eventRow).join(''):`<p>Keine Termine vorhanden.</p>${btn('newEventOnDay',`${ic('plus')} Termin erstellen`,'secondary',`data-date="${esc(e.dataset.date)}"`)}`,()=>true)},newEventOnDay:e=>{$('#modal').close();openEvent(null,e.dataset.date)},editOwnInModal:e=>{$('#modal').close();openEvent(e.dataset.id)},
 prevWeek:()=>{ui.week=addDays(ui.week,-7);render()},nextWeek:()=>{ui.week=addDays(ui.week,7);render()},todayWeek:()=>{ui.week=monday(new Date());render()},prevMonth:()=>{ui.month=new Date(ui.month.getFullYear(),ui.month.getMonth()-1,1);render()},nextMonth:()=>{ui.month=new Date(ui.month.getFullYear(),ui.month.getMonth()+1,1);render()},todayMonth:()=>{ui.month=monthStart(new Date());render()},
 grade:e=>{state.grades[e.dataset.id]=e.value;store();render()},moduleDone:e=>{state.completed[e.dataset.id]=e.checked;store();render()},specialization:e=>{state.specialization=Number(e.value);store();render()},openNote:e=>{ui.noteModule=e.dataset.id;ui.noteView='edit';location.hash='#/lernzettel';render()},selectNote:e=>{ui.noteModule=e.dataset.id;ui.cardsIndex=0;ui.cardFlipped=false;render()},noteMode:e=>{ui.noteView=e.dataset.value;render()},noteInput:e=>{state.notes[ui.noteModule]=e.value;store()},printNote:()=>{const current=state.notes[ui.noteModule];if(!current){toast('Dieser Lernzettel ist noch leer.');return}let name=modName(ui.noteModule);let w=window.open('','_blank');if(!w){toast('Bitte Pop-ups zulassen.');return}w.document.write(`<!doctype html><html lang="de"><meta charset="utf-8"><title>${esc(name)}</title><style>body{font:15px/1.65 Arial;max-width:800px;margin:50px auto;padding:20px}h1,h2{color:#27315d}</style><h1>${esc(name)}</h1>${markdown(current)}</html>`);w.document.close();setTimeout(()=>w.print(),450)},
 newCard:()=>openCard(),flipCard:()=>{ui.cardFlipped=!ui.cardFlipped;render()},nextCard:()=>{ui.cardsIndex=Math.min((state.cards[ui.noteModule]||[]).length-1,ui.cardsIndex+1);ui.cardFlipped=false;render()},prevCard:()=>{ui.cardsIndex=Math.max(0,ui.cardsIndex-1);ui.cardFlipped=false;render()},deleteCard:e=>{state.cards[ui.noteModule]=(state.cards[ui.noteModule]||[]).filter(c=>c.id!==e.dataset.id);ui.cardsIndex=0;store();render()},
 planStep:e=>{const k=e.dataset.group,n=Number(e.dataset.index),s=new Set(state.planning[k]||[]);e.checked?s.add(n):s.delete(n);state.planning[k]=[...s];store();render()},
 focusDuration:e=>{ui.focusLen=+e.dataset.value;ui.remaining=ui.focusLen*60;ui.focusRunning=false;render()},toggleFocus:()=>{updateFocus();ui.focusRunning=!ui.focusRunning;ui.focusStarted=Date.now();render()},resetFocus:()=>{ui.focusRunning=false;ui.remaining=ui.focusLen*60;render()},focusSubject:e=>ui.focusModule=e.value,
 setTheme:e=>{state.theme=e.dataset.value;store();render()},accent:e=>{state.accent=e.dataset.value;store();render()},
 exportBackup,importBackup:()=>fileRead('backupFile',async raw=>{let d=JSON.parse(raw);if(!d.state||!Array.isArray(d.state.tasks)||typeof d.state.notes!=='object')throw Error('Invalid backup');if(!confirm('Vorhandene Daten in diesem Browser durch die Sicherung ersetzen?'))return;for(let k of Object.keys(state))delete state[k];Object.assign(state,d.state);store();render();toast('Sicherung wiederhergestellt')}),exportCalendar:calendarExport,
 importICS:()=>fileRead('icsFile',async raw=>{let a=parseICS(raw);if(!a.length)throw Error('No events');state.ical[state.semester]=a;store();render();toast(`${a.length} Vorlesungen für Semester ${state.semester} importiert`)}),reloadICS:()=>reloadICS(true),importInfo:()=>{location.hash='#/einstellungen';render()},
 resetAll:()=>{if(confirm('Alle Aufgaben, Notizen, Termine und Noten endgültig aus diesem Browser löschen?')){localStorage.removeItem(KEY);location.reload()}},refresh:()=>location.reload()
};
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let name=el.dataset.action;if(['grade','moduleDone','planStep','specialization','focusSubject','noteInput'].includes(name))return;let fn=act[name];if(fn){e.preventDefault();fn(el)}});
document.addEventListener('change',e=>{let el=e.target.closest('[data-action]');if(!el)return;if(['grade','moduleDone','planStep','specialization','focusSubject'].includes(el.dataset.action))act[el.dataset.action](el)});
document.addEventListener('input',e=>{let el=e.target;if(el.dataset.action==='noteInput')act.noteInput(el)});
$('#semesterSelect').addEventListener('change',e=>{state.semester=+e.target.value;ui.noteModule='';store();render()});$('#themeToggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';store();render()});$('#menuBtn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileBackdrop').hidden=false});$('#mobileBackdrop').addEventListener('click',closeMenu);window.addEventListener('hashchange',()=>{closeMenu();render()});
$('#modalClose').addEventListener('click',()=>$('#modal').close());$('#modalCancel').addEventListener('click',()=>$('#modal').close());$('#modalForm').addEventListener('submit',e=>{e.preventDefault();let ok=ui.modalSubmit?.(new FormData(e.target));if(ok!==false){$('#modal').close();render()}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(e.key==='Enter'&&e.target.classList?.contains('flashcard'))act.flipCard()});
setInterval(updateFocus,800);if(!location.hash)location.hash='#/heute';render();if(!state.ical[1]?.length)reloadICS();
})();
